CREATE TABLE `pssubf_ad_hoc_list` (
  `id` int NOT NULL AUTO_INCREMENT,
  `beneficiary_membership_number` varchar(100) NOT NULL,
  `title` varchar(255) DEFAULT NULL,
  `category` varchar(100) DEFAULT NULL,
  `comments` text,
  `date_created` date DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `claim_form_date` date DEFAULT NULL,
  `status` varchar(50) DEFAULT 'Created',
  `supporting_docs_attached` varchar(10) DEFAULT 'No',
  `attachment_path` varchar(255) DEFAULT NULL,
  `years_to_maturity` int DEFAULT '0',
  `affordability_calculation` varchar(20) DEFAULT NULL,
  `portfolio_value` decimal(15,2) DEFAULT '0.00',
  `portfolio_date` date DEFAULT NULL,
  `amount_requested` decimal(15,2) DEFAULT '0.00',
  `date_paid` date DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_adhoc_beneficiary` (`beneficiary_membership_number`),
  CONSTRAINT `fk_adhoc_beneficiary` FOREIGN KEY (`beneficiary_membership_number`) REFERENCES `pssubf_beneficiaries` (`membership_number`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
