INSERT INTO `emails` VALUES ('19910c03ba399c88','Hubble Club <support@hubbleconnected.com>','Hubble Club Verification Code','Wed, 3 Sep 2025 18:04:17 +0000','Hello, You&#39;re two step away from enjoying HubbleClub and all its benefits! Please enter the code below on your app within 30 minutes of receiving it. CODE: 793730 Questions? Reach us here Want more','\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\nHello,\r\n\r\n\r\n\r\n You’re two step away from enjoying HubbleClub and all its benefits! Please \r\nenter the code below on your app within 30 minutes of receiving it.\r\n\r\n\r\n\r\n\r\nCODE: 793730\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n  \r\n\r\n\r\n\r\nQuestions?\r\n\r\n\r\n\r\nReach us here <https://hubbleconnected.com/pages/contact2>\r\n\r\n\r\nWant more? Check out our socials \r\n\r\n\r\n <https://www.instagram.com/hubble.connected/> \r\n<https://www.facebook.com/HubbleConnects> \r\n<https://www.youtube.com/channel/UC99WsxGEojdnQiyk_ytn0xg> \r\n<https://twitter.com/Hubble_Connect>\r\n\r\n\r\n',1756922657000),('19910f66ffeb2710','LinkedIn <updates-noreply@linkedin.com>','Leading Edge Writer recently posted','Wed, 3 Sep 2025 19:03:27 +0000 (UTC)','58% quit their jobs due to toxic work culture. 77% feel suffocated by… ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏ ͏','Jitender Girdhar shared a post: 58% quit their jobs due to toxic work culture.\r\n\r\n77% feel suffocated by micromanagement.\r\n\r\nPeople don’t actually quit jobs.\r\nThey quit the conditions…\r\nLIKE PRAISE EMPATHY 6,892, 402 Comments\r\n\r\n\r\nRead more: https://www.linkedin.com/comm/feed/update/urn:li:activity:7365601686540668928?origin=NETWORK_CONVERSATIONS&lipi=urn%3Ali%3Apage%3Aemail_email_network_conversations_01%3B%2FSgX42AzTzCzZCL9SG12cQ%3D%3D&midToken=AQFb1tRdHVsR7Q&midSig=2NTDsQ7UMTPXU1&trk=eml-email_network_conversations_01-network~post~cta~text-0-read~more&trkEmail=eml-email_network_conversation